// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout, MatrixTriangle } from '@stdlib/types/blas';

/**
* Interface describing `dpbequ`.
*/
interface Routine {
	/**
	* Computes diagonal scaling for a symmetric band matrix.
	*
	* ## Notes
	*
	* -   Full compact AB is (KD+1)-by-N; upper diagonal row KD, lower row zero. KD>=N is supported.
	* -   Selected diagonals must be finite before writes; ignored entries may be nonfinite.
	* -   INFO=0 writes scaling S, SCOND and AMAX. Positive INFO copies every original diagonal into S and writes full AMAX, retaining SCOND's exact sentinel.
	* -   The first nonpositive diagonal gives one-based INFO; strict comparisons preserve the first tied zero sign, differing from sampled reference AMAX failures.
	* -   Active intrinsic Float64Array views require current ordinary backing, stable exclusive lifetime and pairwise disjoint conservative indexed byte envelopes.
	* -   RAB current valid extents are supported; shared/proxy/detached/OOB views are rejected. Hidden foreign physical aliases remain a caller precondition in pure JS.
	* -   Empty calls validate only active disjoint scalar cells after required selectors/dimensions/main LDAB, then write SCOND=1 and AMAX=+0; inactive AB/S metadata is ignored.
	* -   Types cannot express finite values, geometry, lifetime, alias, exact arithmetic or configured native-domain constraints.
	*
	* @param order - row-major (101) or column-major (102) layout
	* @param uplo - upper (121) or lower (122) triangle
	* @param N - matrix order, integer in [0,2147483646]
	* @param KD - bandwidth, integer in [0,2147483646]
	* @param AB - read-only full compact band view
	* @param LDAB - leading dimension, >=KD+1 column-major or >=max(1,N) row-major
	* @param S - output-only N-vector
	* @param SCOND - mutable scalar output at index zero, retained on failure
	* @param AMAX - mutable maximum output at index zero
	* @throws invalid selectors, storage or runtime domain
	* @returns numeric INFO, zero or the first one-based nonpositive diagonal
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var AB = new Float64Array( [ 4.0, 16.0, 64.0 ] );
	* var S = new Float64Array( 3 );
	* var SCOND = new Float64Array( 1 );
	* var AMAX = new Float64Array( 1 );
	* var info = dpbequ( 'column-major', 'lower', 3, 0, AB, 1, S, SCOND, AMAX );
	* // returns 0
	* // S => <Float64Array>[ 0.5, 0.25, 0.125 ]
	* // SCOND => <Float64Array>[ 0.25 ]
	* // AMAX => <Float64Array>[ 64 ]
	*/
	( order: Layout | 101 | 102, uplo: MatrixTriangle | 121 | 122, N: number, KD: number, AB: Float64Array, LDAB: number, S: Float64Array, SCOND: Float64Array, AMAX: Float64Array ): number;

	/**
	* Computes diagonal scaling for a symmetric band matrix with alternative indexing.
	*
	* ## Notes
	*
	* -   Full compact AB is (KD+1)-by-N; upper diagonal row KD, lower row zero. KD>=N is supported.
	* -   Selected diagonals must be finite before writes; ignored entries may be nonfinite.
	* -   INFO=0 writes scaling S, SCOND and AMAX. Positive INFO copies every original diagonal into S and writes full AMAX, retaining SCOND's exact sentinel.
	* -   The first nonpositive diagonal gives one-based INFO; strict comparisons preserve the first tied zero sign, differing from sampled reference AMAX failures.
	* -   Active intrinsic Float64Array views require current ordinary backing, stable exclusive lifetime and pairwise disjoint conservative indexed byte envelopes.
	* -   RAB current valid extents are supported; shared/proxy/detached/OOB views are rejected. Hidden foreign physical aliases remain a caller precondition in pure JS.
	* -   Empty calls validate only active disjoint scalar cells after required selectors/dimensions/main LDAB, then write SCOND=1 and AMAX=+0; inactive AB/S metadata is ignored.
	* -   Types cannot express finite values, geometry, lifetime, alias, exact arithmetic or configured native-domain constraints.
	*
	* @param uplo - upper (121) or lower (122) triangle
	* @param N - matrix order, integer in [0,2147483646]
	* @param KD - bandwidth, integer in [0,2147483646]
	* @param AB - read-only full compact band view
	* @param strideAB1 - band-row element stride
	* @param strideAB2 - matrix-column element stride
	* @param offsetAB - band starting element offset
	* @param S - output-only N-vector
	* @param strideS - output-vector element stride
	* @param offsetS - output-vector starting offset
	* @param SCOND - mutable scalar output, retained on failure
	* @param offsetSCOND - active SCOND scalar offset
	* @param AMAX - mutable maximum output
	* @param offsetAMAX - active AMAX scalar offset
	* @throws invalid selectors, storage or runtime domain
	* @returns numeric INFO, zero or the first one-based nonpositive diagonal
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var AB = new Float64Array( [ 4.0, -0.0, 16.0, 25.0 ] );
	* var S = new Float64Array( 4 );
	* var SCOND = new Float64Array( [ -7.0 ] );
	* var AMAX = new Float64Array( 1 );
	* var info = dpbequ.ndarray( 'lower', 4, 0, AB, 1, 1, 0, S, 1, 0, SCOND, 0, AMAX, 0 );
	* // returns 2
	* // S => <Float64Array>[ 4, -0, 16, 25 ]
	* // SCOND => <Float64Array>[ -7 ]
	* // AMAX => <Float64Array>[ 25 ]
	*/
	ndarray( uplo: MatrixTriangle | 121 | 122, N: number, KD: number, AB: Float64Array, strideAB1: number, strideAB2: number, offsetAB: number, S: Float64Array, strideS: number, offsetS: number, SCOND: Float64Array, offsetSCOND: number, AMAX: Float64Array, offsetAMAX: number ): number;
}

/**
* Computes diagonal scaling factors for a symmetric band matrix.
*/
declare var dpbequ: Routine;


// EXPORTS //

export = dpbequ;
